from CHB_ASSET_INFO info


        left join (
        SELECT asset_code,rating FROM (
        select
        @rownum := @rownum + 1 rownum
        ,brating.O_CODE as asset_code
        ,brating.GRADE_RESULT as rating,
        IF( @O_CODE = brating.O_CODE, @rank := @rank + 1, @rank := 1 ) AS my_rank,
        @O_CODE := brating.O_CODE
        from
        ( SELECT * FROM MST_BOND_CREDIT_RATING ORDER BY O_CODE, GRADE_DATE desc
         /*推荐评级*/
            ,is_recommand asc

         /*最大评级*/
            ,GRADE_RESULT asc

         /*最小评级*/
